{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C03"],
      "claim": "Bumetanide, the closest structural analogue as a sulfamoylbenzoic acid loop diuretic, had an absolute oral bioavailability of 80% versus IV in normal subjects, with other records ranging from 74% to 96%, strongly supporting high F for the query's similar carboxylic acid/sulfonamide/arylamine scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C35"],
      "claim": "In patients with cirrhosis, metoclopramide had an absolute oral bioavailability of 79.0 ± 18.8% (range 49–103%), directly showing that cirrhosis does not preclude high oral F for a small molecule with first-pass metabolism.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "In patients with alcoholic cirrhosis, tolfenamic acid, an anthranilic acid derivative with a carboxylic acid and secondary amine, showed about 100% oral bioavailability, supporting high F for the query under the same disease condition.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C59"],
      "claim": "Azosemide, a structurally related sulfamoylbenzoic acid loop diuretic, had an absolute oral bioavailability of approximately 20.4% in healthy fasting humans, a borderline/low value; however, its tetrazole acid bioisostere and thiophene substituent differ from the query's carboxylic acid and furan, reducing direct transferability.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is furosemide, a sulfamoylbenzoic acid loop diuretic. The closest high-transfer analogue bumetanide shows consistently high absolute oral bioavailability (74–96%), and direct cirrhosis-condition evidence from metoclopramide and tolfenamic acid also shows high F. The only low-direction analogue, azosemide, is structurally related but has a tetrazole acid bioisostere and thiophene rather than the query's carboxylic acid/furan; its borderline ~20% value does not outweigh the strong high-F evidence. Prediction: high.",
  "evidence_gaps": [
    "No direct furosemide bioavailability record is present in the supplied evidence; prediction relies on close analogues.",
    "Cirrhosis-specific data are available only for metoclopramide and tolfenamic acid, not for sulfamoylbenzoic acid loop diuretics; hepatic disease effects on this scaffold are inferred."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

